onClick:
{{ 
  storeValue('activeVentil', currentItem.Ventil_Rechts); 
  storeValue('selectedProg', ''); // Setzt das Programm beim Öffnen auf "leer" zurück
  showModal('Modal_Programm'); 
}}

text:
{{
  (() => {
    // 1. Linkes Ventil identifizieren
    const rawVal = String(currentItem.Ventil_Rechts || "").trim();
    if (!rawVal) return "";

    const btnVal = parseFloat(rawVal).toFixed(2);

    // 2. Leer-Status prüfen (Stammdaten & Store)
    const isLeer = currentItem.Status_Leer_Rechts === true || String(currentItem.Status_Leer_Rechts).toUpperCase() === "TRUE";
    if (appsmith.store['Ventil_Leer_' + btnVal] || isLeer) {
      return btnVal;
    }

    // 3. Alle Einträge für dieses Ventil filtern (Store bevorzugt, Fallback Query)
    const bewaesserungQuelle = appsmith.store.lokaleBewaesserungData || Bewaesserung_Lesen.data || [];
    const filter = bewaesserungQuelle.filter(row => 
      parseFloat(row.Ventil || 0).toFixed(2) === btnVal
    );

    // Ventilname formatieren
    const formattedName = btnVal.startsWith("2") ? "2. " + btnVal : btnVal;

    // 4. Tage-Berechnung über das zentrale Helper-Objekt
    if (filter.length === 0) return formattedName;

    const statusText = Data_Helper.getTageHer(filter);

    return `${formattedName} (${statusText})`;
  })()
}}
